from flask import Flask, request, jsonify
import os
from werkzeug.utils import secure_filename
import sqlite3

app = Flask(__name__)

# Database setup
def init_db():
    conn = sqlite3.connect('photos.db')
    c = conn.cursor()
    c.execute('''CREATE TABLE IF NOT EXISTS photos
                 (id INTEGER PRIMARY KEY, name TEXT, price REAL, description TEXT, filename TEXT)''')
    c.execute('''CREATE TABLE IF NOT EXISTS pending_photos
                 (id INTEGER PRIMARY KEY, name TEXT, price REAL, description TEXT, filename TEXT)''')
    conn.commit()
    conn.close()

@app.route('/upload', methods=['POST'])
def upload_file():
    if 'file' not in request.files:
        return "No file part", 400
    file = request.files['file']
    if file.filename == '':
        return "No selected file", 400
    if file:
        filename = secure_filename(file.filename)
        file.save(os.path.join("uploads/", filename))

        # Extract other form data
        name = request.form.get('name')
        price = float(request.form.get('price'))
        description = request.form.get('description')

        # Check for duplicate names
        conn = sqlite3.connect('photos.db')
        c = conn.cursor()
        c.execute("SELECT * FROM photos WHERE name=?", (name,))
        existing_photo = c.fetchone()

        if existing_photo:
            # Store duplicate photo in pending table
            c.execute("INSERT INTO pending_photos (name, price, description, filename) VALUES (?, ?, ?, ?)",
                      (name, price, description, filename))
            conn.commit()
            conn.close()
            return f"Duplicate name {name}, please contact admin to resolve.", 409

        # Insert new photo details into database
        c.execute("INSERT INTO photos (name, price, description, filename) VALUES (?, ?, ?, ?)",
                  (name, price, description, filename))
        conn.commit()
        conn.close()

        return "File uploaded successfully", 200

@app.route('/admin/resolve_duplicate', methods=['POST'])
def resolve_duplicate():
    photo_id = request.form.get('id')
    action = request.form.get('action')  # 'keep' or 'delete'
    conn = sqlite3.connect('photos.db')
    c = conn.cursor()
    c.execute("SELECT * FROM pending_photos WHERE id=?", (photo_id,))
    pending_photo = c.fetchone()

    if pending_photo:
        if action == 'keep':
            c.execute("INSERT INTO photos (name, price, description, filename) VALUES (?, ?, ?, ?)",
                      (pending_photo[1], pending_photo[2], pending_photo[3], pending_photo[4]))
            c.execute("DELETE FROM pending_photos WHERE id=?", (photo_id,))
        elif action == 'delete':
            c.execute("DELETE FROM pending_photos WHERE id=?", (photo_id,))
    conn.commit()
    conn.close()
    return "Resolved", 200

@app.route('/search', methods=['GET'])
def search_photos():
    query = request.args.get('query', '')
    conn = sqlite3.connect('photos.db')
    c = conn.cursor()
    c.execute("SELECT * FROM photos WHERE name LIKE ? OR description LIKE ?", ('%' + query + '%', '%' + query + '%'))
    results = c.fetchall()
    conn.close()

    # Format results for JSON response
    formatted_results = [{"name": r[1], "price": r[2], "description": r[3], "filename": r[4]} for r in results]
    return jsonify(formatted_results)

@app.route('/compare', methods=['GET'])
def compare_photos():
    sort_by = request.form.get('sort_by', 'price')  # Default sorting by price
    order = request.form.get('order', 'asc')  # Default ascending order
    conn = sqlite3.connect('photos.db')
    c = conn.cursor()
    c.execute(f"SELECT * FROM photos ORDER BY {sort_by} {order.upper()}")
    results = c.fetchall()
    conn.close()

    # Format results for JSON response
    formatted_results = [{"name": r[1], "price": r[2], "description": r[3], "filename": r[4]} for r in results]
    return jsonify(formatted_results)

if __name__ == '__main__':
    init_db()
    app.run(debug=True)
```

### Explanation

- **Database Tables**: Two tables are created: `photos` for storing accepted photos and `pending_photos` for storing duplicates until resolved by an administrator.
- **Upload Endpoint**: Handles photo uploads and checks for duplicate names. If a duplicate is found, the photo is stored in the `pending_photos` table.
- **Duplicate Resolution Endpoint**: Allows administrators to resolve duplicates by either keeping or deleting the pending photo.
- **Search Endpoint**: Allows searching through photos based on name or description.
- **Sorting Endpoint**: Provides sorting functionality for photos based on price, name, or description.

